<template><div class="page">
  <section class="hero"><div><p class="eyebrow">Inventory overview</p><h1>Turn every part into<br><span>possibility.</span></h1><p>Track vehicles, organize parts, and manage every listing from one focused workspace.</p><router-link to="/vehicles" class="btn btn-primary">View inventory <AppIcon name="arrow" /></router-link></div>
    <div class="hero-graphic" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-mark"><AppIcon name="car" /></div><div class="float-card card-one"><AppIcon name="box" /><span><strong>{{ stats.parts }}</strong> parts</span></div><div class="float-card card-two"><AppIcon name="tag" /><span><strong>{{ stats.listings }}</strong> listings</span></div></div>
  </section>
  <section class="stat-grid"><article v-for="item in statCards" :key="item.label" class="stat-card panel"><span class="stat-icon"><AppIcon :name="item.icon" /></span><div><p>{{ item.label }}</p><strong>{{ item.value }}</strong><small>{{ item.note }}</small></div></article></section>
  <section><p class="eyebrow">Quick access</p><h2>Keep things moving</h2><div class="action-grid"><router-link v-for="action in actions" :key="action.to" :to="action.to" class="action-card panel"><span class="action-icon"><AppIcon :name="action.icon" /></span><div><h3>{{ action.title }}</h3><p>{{ action.text }}</p></div><AppIcon name="arrow" class="action-arrow" /></router-link></div></section>
</div></template>
<script setup>
import {computed,onMounted,reactive} from 'vue';import superagent from 'superagent';import {apiUrl} from '../api';import AppIcon from '../components/AppIcon.vue'
const stats=reactive({vehicles:0,parts:0,listings:0,value:0});const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v)
const statCards=computed(()=>[{label:'Vehicles',value:stats.vehicles,note:'in your workspace',icon:'car'},{label:'Parts cataloged',value:stats.parts,note:'ready to manage',icon:'box'},{label:'Active listings',value:stats.listings,note:'across marketplaces',icon:'tag'},{label:'Est. inventory value',value:money(stats.value),note:'based on part values',icon:'dashboard'}])
const actions=[{to:'/vehicles',icon:'car',title:'Manage vehicles',text:'Add purchases and browse their parts.'},{to:'/parts',icon:'box',title:'Browse parts',text:'See your complete parts inventory.'},{to:'/view-listing',icon:'tag',title:'Review listings',text:'Track marketplace listings and sales.'}]
onMounted(async()=>{try{const[v,p,l]=await Promise.all([superagent.get(apiUrl('/vehicles/v1')),superagent.get(apiUrl('/parts/v1')),superagent.get(apiUrl('/listings/v1'))]);const parts=Array.isArray(p.body)?p.body:[];stats.vehicles=Array.isArray(v.body)?v.body.length:0;stats.parts=parts.length;stats.listings=Array.isArray(l.body)?l.body.filter(x=>!['SOLD','ENDED'].includes(x.status)).length:0;stats.value=parts.reduce((s,x)=>s+Number(x.est_value_c||0),0)}catch{}})
</script>
