-size:.75rem;font-weight:700}.stat-card strong{display:block;font:800 1.5rem Manrope,sans-serif}.stat-card small{display:block;margin-top:3px;color:var(--muted);font-size:.69rem}section>h2{margin:0;font:800 1.55rem Manrope,sans-serif;letter-spacing:-.04em}.action-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}.action-card{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:15px;padding:22px;text-decoration:none;transition:.2s ease}.action-card:hover{transform:translateY(-3px);border-color:color-mix(in srgb,var(--brand) 45%,var(--border));color:var(--text)}.action-card h3{margin:0 0 5px;font-size:.95rem}.action-card p{margin:0;color:var(--muted);font-size:.78rem;line-height:1.4}.action-arrow{color:var(--muted);width:17px}@media(max-width:1100px){.stat-grid{grid-template-columns:1fr 1fr}.hero{grid-template-columns:1fr}.hero-graphic{display:none}}@media(max-width:700px){.hero{min-height:auto;padding:34px 26px}.hero h1 br{display:none}.stat-grid,.action-grid{grid-template-columns:1fr}.stat-grid{margin-bottom:38px}}
